using System.Collections.Generic;public class Solution{public int Calculate(string s){var st=new Stack<int>();int r=0,n=0,sg=1;for(int i=0;i<=s.Length;i++){char c=i<s.Length?s[i]:'\0';if(char.IsDigit(c))n=n*10+c-'0';else if(c=='+'||c=='-'){r+=sg*n;n=0;sg=c=='+'?1:-1;}else if(c=='('){st.Push(r);st.Push(sg);r=0;sg=1;}else if(c==')'){r+=sg*n;n=0;r=st.Pop()*r+st.Pop();}else if(c=='\0')r+=sg*n;}return r;}}
